    writejson('programme_hypotheses.json',{'package_id':'P02I','version':'1.0','as_of':ASOF,'scope':'Международные альтернативы дополнительно к самостоятельному CASE_SJ; не утверждённая сеть/не финансовый прогноз','independent_core':'CASE_SJ продолжается при любой незавершённости международного допуска/Ту214','prioritisation':'I01/I02/I03 — рекомендуемые первые matched проверки по силе документированного механизма. Прочие не экономически отвергнуты. Численных весов нет.','hypotheses':out})
